"""Build manifest n01-2026-10-06-w9: control sample 13 findings + whole-bank LaTeX scan fixes.

Reads the local DB only; never writes to it. Usage (from content-service):
  CONTENT_REPAIR_DATABASE_URL=... [W9_SCRATCH=dir] python3 -m tools.content_review.build_w9_sample13

Part A (sample 13): key / condition / distractor-value / distractor-explanation / correct-distractor / latex fixes.
  Every new distractor value was recomputed (python3/sympy or by hand); the explanation of each rewritten
  distractor describes a concrete mistake that yields exactly that value. Key changes only with a proof in `evidence`.
Part B (LaTeX scan): duplicate options (options rebuilt as key + explained distractors), broken decimals
  ($1-0$,$64$ -> $1-0{,}64$, also in question_text when question_latex is already correct), `\\\\x` before a letter,
  broken \\dfrac markup, Cyrillic inside math.
Multi-part tasks (MULTI) are NOT touched here; they are listed for the split pipeline.
"""
from __future__ import annotations

import collections
import json
import os
import re
import sys
from pathlib import Path

from sqlalchemy import create_engine, text

from tools.content_review import guarded_repair as gr

BATCH = "n01-source-repair-2026-10-06-w9"
OUT = Path(__file__).resolve().parents[2] / "data/content_repairs/n01-2026-10-06-w9.json"
EDITS: dict = {}


def S(tid, cls, reason, evidence, **kw):
    """Register (or merge into) the edit spec of one task.

    d = {distractor_index: (value|None, value_latex|None, explanation|None)}; None keeps the old field.
    dset = [(value, value_latex, explanation), ...] replaces the whole distractor list.
    """
    e = EDITS.setdefault(tid, {"cls": [], "reason": [], "evidence": [], "d": {}})
    for c in cls.split("+"):
        if c not in e["cls"]:
            e["cls"].append(c)
    e["reason"].append(reason)
    e["evidence"].append(evidence)
    e["d"].update(kw.pop("d", {}))
    e.update(kw)


# ------------------------------------------------------------------ helpers
BD_PAT = re.compile(r"(?<=\d)\$,\$(?=[\d*\[(])")
DEC = re.compile(r"\d+(?:\{,\}|,)\d+")


def bd(s: str) -> str:
    return BD_PAT.sub("{,}", s) if s else s


def bdx(s: str) -> str:
    return (bd(s).replace("$√0{,}36=0{,}6$", r"$\sqrt{0{,}36}=0{,}6$")
            .replace("$a_13=-20{,}7+1{,}8·12=0{,}9>0$", r"$a_{13}=-20{,}7+1{,}8\cdot12=0{,}9>0$"))


def dbl_bs(s: str) -> str:
    return re.sub(r"(?<!\\)\\\\(?=[A-Za-z])", lambda m: "\\\\ ", s) if s else s


def canon(s: str) -> str:
    s = (s or "").replace("\\dfrac", "\\frac").replace("{,}", ",").replace("\\left", "").replace("\\right", "")
    s = s.replace("\\,", "").replace("\;", "")
    return re.sub(r"[\s$]", "", s).replace(",", ".")


def dec_tokens(s: str) -> collections.Counter:
    return collections.Counter(t.replace("{,}", ",") for t in DEC.findall(s or ""))


def norm_dm(d: dict) -> dict:
    d = dict(d)
    el = d.get("error_logic") or d.get("explanation") or ""
    ell = d.get("error_logic_latex") or d.get("explanation_latex") or el
    d.update(error_logic=el, explanation=el, error_logic_latex=ell, explanation_latex=ell)
    d.setdefault("value_latex", d["value"])
    return d


def set_expl(d: dict, expl: str) -> None:
    d.update(error_logic=expl, explanation=expl, error_logic_latex=expl, explanation_latex=expl)


def consistent(opts, optsl, key, dm) -> bool:
    if not opts or len(opts) != len(optsl) or not all(isinstance(o, str) and o.strip() for o in opts):
        return False
    vals = [d["value"] for d in dm]
    return (len(set(opts)) == len(opts) and opts.count(key) == 1 and len(set(vals)) == len(vals)
            and set(vals) == set(opts) - {key})


