# ------------------------------------------------------------------ build
def build_changes(row: dict, spec: dict) -> dict:
    ch: dict = {}
    key, keyl = row["correct_answer"], row["correct_answer_latex"]
    if spec.get("key"):
        key, keyl = spec["key"]
    if (key, keyl) != (row["correct_answer"], row["correct_answer_latex"]):
        ch.update(correct_answer=key, correct_answer_latex=keyl)
    # question
    qt, ql = row["question_text"], row["question_latex"]
    if spec.get("q"):
        nt, nl = spec["q"][0], spec["q"][-1]
    elif spec.get("q_mirror"):
        nt = nl = ql
    else:
        nt = bd(qt)
        nl = bd(ql) if BD_PAT.search(ql or "") else ql
        if spec.get("fix_dbl_bs"):
            nt, nl = dbl_bs(nt), dbl_bs(nl)
    if (nt, nl) != (qt, ql):
        ch.update(question_text=nt, question_latex=nl)
    # distractors
    dm0 = [norm_dm(d) for d in (row["distractor_meta"] or [])]
    dm = [dict(d) for d in dm0]
    old_vals = [d["value"] for d in dm0]
    if spec.get("bd_dm") or spec.get("dset") or spec["d"]:
        for d in dm:
            for f in ("value", "value_latex", "error_logic", "explanation", "error_logic_latex", "explanation_latex"):
                d[f] = bdx(d[f]) if spec.get("bd_dm") else bd(d[f])
    if spec.get("dset"):
        tpl = dm0[0] if dm0 else {"error_type": "manual_review", "plausibility": 0.7}
        dm = []
        for val, vl, expl in spec["dset"]:
            d = {"value": val, "value_latex": vl or val, "error_type": tpl.get("error_type", "manual_review"),
                 "plausibility": tpl.get("plausibility", 0.7)}
            set_expl(d, expl)
            dm.append(d)
    for i, (val, vl, expl) in spec["d"].items():
        if val is not None:
            dm[i]["value"] = val
            dm[i]["value_latex"] = vl or val
        if expl is not None:
            set_expl(dm[i], expl)
    dm_changed = bool(spec.get("dset") or spec["d"] or spec.get("bd_dm")) and dm != (row["distractor_meta"] or [])
    # options
    old, oldl = list(row["answer_options"] or []), list(row["answer_options_latex"] or [])
    new_opts = None
    if (spec.get("rebuild") or dm_changed or "correct_answer" in ch) and (old or spec.get("rebuild")) and dm:
        opts, optsl = list(old), list(oldl)
        ok = (not spec.get("rebuild") and len(old) == len(oldl) and all(isinstance(o, str) for o in old)
              and (key, keyl) == (row["correct_answer"], row["correct_answer_latex"]))
        if ok:
            for i, d in enumerate(dm):
                if d["value"] != old_vals[i]:
                    idx = next((j for j, o in enumerate(opts) if o == old_vals[i] or canon(o) == canon(old_vals[i])), None)
                    if idx is None:
                        ok = False
                        break
                    opts[idx], optsl[idx] = d["value"], d["value_latex"]
        if not (ok and consistent(opts, optsl, key, dm)):
            opts, optsl = [key] + [d["value"] for d in dm], [spec.get("keydisp") or keyl] + [d["value_latex"] for d in dm]
        if opts != old or optsl != oldl:
            new_opts = (opts, optsl)
    if new_opts:
        ch.update(answer_options=new_opts[0], answer_options_latex=new_opts[1])
    if dm_changed:
        ch["distractor_meta"] = dm
    # own quality checks
    if dm and (dm_changed or new_opts or "correct_answer" in ch):
        vals = [canon(d["value"]) for d in dm]
        if len(set(vals)) != len(vals) or canon(key) in vals or len(dm) < 2:
            raise ValueError(f"{row['id']}: distractors not distinct / equal to key / fewer than 2: {vals} key={canon(key)}")
        for d in dm:
            if not d["error_logic"].strip():
                raise ValueError(f"{row['id']}: empty distractor explanation")
    return ch


def summarize(row: dict, ch: dict, spec: dict) -> str:
    parts = []
    if "correct_answer" in ch:
        old, new = spec.get("keychange", (row["correct_answer"], ch["correct_answer"]))
        parts.append(f"key {old} -> {new}")
    if spec.get("condchange"):
        parts.append(f"cond {spec['condchange'][0]} -> {spec['condchange'][1]}")
    elif "question_text" in ch:
        parts.append(f"question {row['question_text'][:70]!r} -> {ch['question_text'][:70]!r}")
    if "distractor_meta" in ch:
        olds = [d.get("value") for d in row["distractor_meta"] or []]
        for i, d in enumerate(ch["distractor_meta"]):
            if i >= len(olds) or d["value"] != olds[i]:
                parts.append(f"d{i} {olds[i] if i < len(olds) else '-'} -> {d['value']}")
            else:
                old = norm_dm((row["distractor_meta"] or [])[i])
                if old["error_logic"] != d["error_logic"] or old["error_logic_latex"] != d["error_logic_latex"]:
                    parts.append(f"d{i} expl")
    if "answer_options" in ch:
        parts.append("options rebuilt")
    return "; ".join(parts)


def entry(row: dict, ch: dict, spec: dict) -> dict:
    e = {"id": row["id"], "before_sha256": gr.fingerprint(row), "reason": "; ".join(spec["reason"]),
         "evidence": " ".join(spec["evidence"]), "changes": ch}
    gr.validate_entry(e)
    after = gr.candidate(row, e, BATCH)
    if any(k in ch for k in ("answer_options", "correct_answer", "distractor_meta")):
        gr.validate_choices(after)
    e["after_sha256"] = gr.fingerprint(after)
    return e


def kx_strings(ch: dict) -> list:
    out = [ch.get(k) for k in ("question_text", "question_latex", "correct_answer", "correct_answer_latex")]
    out += ch.get("answer_options_latex", [])
    for d in ch.get("distractor_meta", []):
        out += [d["value_latex"], d["error_logic_latex"]]
    return [s for s in out if s]


def main() -> None:
    engine = create_engine(os.environ["CONTENT_REPAIR_DATABASE_URL"])
    scratch = os.environ.get("W9_SCRATCH")
    with engine.connect() as conn:
        bulk = [r[0] for r in conn.execute(text(
            "SELECT id FROM tasks_master WHERE is_active AND (question_text ~ '\\d\\$,\\$\\d' "
            "OR question_latex ~ '\\d\\$,\\$\\d') ORDER BY id"))]
        ids = sorted(set(EDITS) | set(bulk))
        rows = {}
        for i in range(0, len(ids), 500):
            rows.update({r["id"]: r for r in gr._load(conn, ids[i:i + 500], False)})
    repairs, lines, kx, skipped, inactive = [], [], {}, [], []
    stats = collections.Counter()
    for tid in ids:
        row = rows[tid]
        if not row["is_active"]:
            inactive.append(tid)
            continue
        spec = EDITS.get(tid)
        auto = spec is None
        if auto:
            spec = {"cls": ["broken_decimal"], "d": {},
                    "reason": ["сломана запись десятичных дробей в question_text ($2$,$4$ вместо $2{,}4$); question_latex уже корректен"],
                    "evidence": ["Склеенные фрагменты $a$,$b$ в question_text объединены в $a{,}b$ (число с десятичной запятой); "
                                 "те же числа записаны в question_latex через {,}; question_latex, ключ и варианты не менялись."]}
        ch = build_changes(row, spec)
        if auto:
            nt = ch.get("question_text", row["question_text"])
            if "question_text" not in ch or any(dec_tokens(nt)[t] > dec_tokens(row["question_latex"])[t] for t in dec_tokens(nt)):
                skipped.append(tid)
                continue
        if not ch:
            skipped.append(tid)
            continue
        e = entry(row, ch, spec)
        repairs.append(e)
        kx[tid] = kx_strings(ch)
        cls = "+".join(spec["cls"])
        stats[cls] += 1
        lines.append((tid, cls, summarize(row, ch, spec), " ".join(spec["evidence"]), spec))
    manifest = {"batch": BATCH, "mode": "in_place_owner_requested", "source_checked_at": "2026-10-06T00:00:00Z",
                "student_data_included": False, "repairs": repairs}
    OUT.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n")
    print(OUT)
    keyc = [l for l in lines if l[4].get("keychange")]
    condc = [l for l in lines if l[4].get("condchange")]
    print(f"manifest entries: {len(repairs)}; key changes: {len(keyc)}; condition changes: {len(condc)}; "
          f"deactivations: 0; multi listed: {len(MULTI)}")
    print("by class:", dict(stats))
    print(f"skipped (no change / text tokens not in latex): {len(skipped)} {skipped[:5]}; inactive in scan: {inactive}")
    if scratch:
        Path(scratch, "w9_kx.json").write_text(json.dumps(kx, ensure_ascii=False))
        tsv = ["## KEY CHANGES", "id\tclass\told -> new\tproof"]
        tsv += [f"{i}\t{c}\t{s}\t{p}" for i, c, s, p, sp in keyc]
        tsv += ["## CONDITION CHANGES"] + [f"{i}\t{c}\t{s}\t{p}" for i, c, s, p, sp in condc]
        tsv += ["## MULTI (not touched, for split pipeline)"] + [f"{m}\tmulti\t-\tнезависимые подвопросы" for m in MULTI]
        tsv += ["## ALL OTHER EDITS"]
        done = {l[0] for l in keyc + condc}
        tsv += [f"{i}\t{c}\t{s}\t{p}" for i, c, s, p, sp in lines if i not in done]
        Path(scratch, "w9_changes.tsv").write_text("\n".join(t.replace("\n", " ") for t in tsv) + "\n")


if __name__ == "__main__":
    main()
